  const sourceText=new WeakMap();
  function translateText(text,target){const lead=text.match(/^\s*/)?.[0]||'',tail=text.match(/\s*$/)?.[0]||'',key=text.trim();if(target==='vi')return (inverse[key]!==undefined?lead+inverse[key]+tail:text);const table=target==='en'?words:localePhrases[target];if(table?.[key]!==undefined)return lead+table[key]+tail;return lead+(words[key]??key)+tail}
  function translatePageText(){const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let n;while(n=walker.nextNode()){if(n.parentElement?.closest('script,style'))continue;if(!sourceText.has(n))sourceText.set(n,n.nodeValue);n.nodeValue=translateText(sourceText.get(n),lang)}}
  function setLanguage(next){lang=next;storage.set('polarisLanguage',lang);document.documentElement.lang=lang;document.documentElement.dir=['ar','fa','ur'].includes(lang)?'rtl':'ltr';$('#languageToggle').value=lang;syncLanguagePicker();translatePageText();const languageSearch=$('#languageSearch');if(languageSearch)languageSearch.placeholder=lang==='fr'?'Rechercher une langue…':lang==='en'?'Search languages…':lang==='ja'?'言語を検索…':lang==='ko'?'언어 검색…':'Tìm ngôn ngữ...';const search=$('#fieldSearch');if(search)search.placeholder=lang==='en'?'Search fields, skills...':lang==='fr'?'Rechercher un domaine ou une compétence…':lang==='ja'?'分野やスキルを検索…':lang==='ko'?'분야와 기술 검색…':'Tìm lĩnh vực, kỹ năng...';const chat=$('#chatInput');if(chat)chat.placeholder=lang==='en'?'Ask Wisp what’s on your mind...':lang==='fr'?'Posez votre question à Wisp…':lang==='ja'?'Wispに気軽に話しかけてください…':lang==='ko'?'Wisp에게 편하게 물어보세요…':'Hỏi Wisp điều bạn đang nghĩ...';renderKnowledge();updateGreeting();updateProgress()}
